import type { FrameworkId, FrameworkRef, Rule } from "../types";

/**
 * Unified control library.
 * Each control is written once against the Security Baseline Model and
 * cross-referenced to CIS, NIST SP 800-53 r5, DISA STIG/SRG and ISO/IEC
 * 27001:2022. Selecting a framework filters and re-labels the findings;
 * adding a framework is adding references, not code.
 *
 * Reference IDs are seeded from public benchmark documents and should be
 * validated against the licensed benchmark edition before formal use.
 */

export const FRAMEWORKS: Record<FrameworkId, { name: string; short: string; publisher: string; edition: string; blurb: string }> = {
  cis: { name: "CIS Benchmarks", short: "CIS", publisher: "Center for Internet Security", edition: "Cisco IOS 17.x v2 / vendor L1 profiles", blurb: "Prescriptive, vendor-specific hardening controls. Level 1 profile." },
  nist: { name: "NIST SP 800-53 Rev. 5", short: "NIST", publisher: "NIST", edition: "Rev. 5 (Sep 2020)", blurb: "Security and privacy control families (AC, AU, CM, IA, SC, SI)." },
  stig: { name: "DISA STIG / SRG", short: "STIG", publisher: "DISA", edition: "Network Device Management SRG v5 · Router SRG", blurb: "Department of Defense requirements for network device management and routers." },
  iso: { name: "ISO/IEC 27001:2022", short: "ISO", publisher: "ISO/IEC", edition: "Annex A (2022)", blurb: "Information security management controls, Annex A technological controls." },
};

const cis = (id: string, title: string): FrameworkRef => ({ framework: "cis", id, title });
const nist = (id: string, title: string): FrameworkRef => ({ framework: "nist", id, title });
const stig = (id: string, title: string): FrameworkRef => ({ framework: "stig", id, title });
const iso = (id: string, title: string): FrameworkRef => ({ framework: "iso", id, title });

const NIST_AC17 = nist("AC-17(2)", "Remote Access — Protection of Confidentiality and Integrity Using Encryption");
const NIST_SC8 = nist("SC-8(1)", "Transmission Confidentiality and Integrity — Cryptographic Protection");
const NIST_SC8_BASE = nist("SC-8", "Transmission Confidentiality and Integrity");
const NIST_CM7 = nist("CM-7", "Least Functionality");
const NIST_CM6 = nist("CM-6", "Configuration Settings");
const NIST_AU2 = nist("AU-2", "Event Logging");
const NIST_AU12 = nist("AU-12", "Audit Record Generation");
const NIST_IA5 = nist("IA-5(1)", "Authenticator Management — Password-based Authentication");
const NIST_SC12 = nist("SC-12", "Cryptographic Key Establishment and Management");
const NIST_SC23 = nist("SC-23", "Session Authenticity");
const STIG_CRYPTO_CONF = stig("SRG-APP-000412-NDM-000331", "Protect the confidentiality of nonlocal maintenance communications");
const STIG_UNNECESSARY = stig("SRG-APP-000142-NDM-000245", "Prohibit the use of unnecessary functions, ports, protocols and services");
const STIG_ROUTING_AUTH = stig("SRG-NET-000230-RTR-000001", "Authenticate all routing protocol messages using NIST-approved message authentication codes");
const ISO_NET = iso("A.8.20", "Networks security");
const ISO_CRYPTO = iso("A.8.24", "Use of cryptography");
const ISO_LOG = iso("A.8.15", "Logging");
const ISO_AUTH = iso("A.8.5", "Secure authentication");
const ISO_CONF = iso("A.8.9", "Configuration management");
const ISO_AUTHINFO = iso("A.5.17", "Authentication information");

const IOS_XE_NOTE = "Requires IOS-XE 16.x or later; classic IOS 15.x images cannot restrict SSH algorithms or use TLS syslog — plan an image upgrade.";

