    remediation: { "cisco-ios": "interface <each-l3-interface>\n no ip redirects\n no ip unreachables\n no ip mask-reply", "cisco-nxos": "interface <each-l3-interface>\n  no ip redirects", "arista-eos": "interface <each-l3-interface>\n   no ip redirects", "juniper-junos": "set system no-redirects\ncommit", "huawei-vrp": "interface <each-interface>\n undo icmp redirect send", "mikrotik-routeros": "/ip settings set send-redirects=no", generic: "Disable ICMP redirects on L3 interfaces." },
